  "knowledge": "Approval Rate (AR)",
  "description": "Calculates the percentage of certified applications out of total applications.",
  "definition": "AR = (Number of Certified Applications / Total Number of Applications) \u00d7 100%. Application status is tracked as part of the application data."
}
